def test_load_hooked_model_without_pretrained_uses_empty_state_dict(monkeypatch):
    monkeypatch.setattr(model_loader, "check_model_name", lambda name, allow_failing=False: name)
    monkeypatch.setattr(model_loader, "load_config", lambda *args, **kwargs: object())

    load_weights_called = False

    def fake_load_weights(*args, **kwargs):
        nonlocal load_weights_called
        load_weights_called = True
        return {}

    monkeypatch.setattr(model_loader, "load_weights", fake_load_weights, raising=False)

    model = model_loader.load_hooked_model(
        "dummy-model",
        model_class=DummyModel,
        pretrained=False,
        device="cpu",
        dtype=torch.float32,
        move_to_device=False,
    )

    assert isinstance(model, DummyModel)
    assert model.loaded_state_dict == {}
    assert not load_weights_called
